```python
from fastapi.exceptions import RequestValidationError
from starlette.requests import Request
from starlette.responses import JSONResponse
from starlette.status import HTTP_422_UNPROCESSABLE_ENTITY
from decimal import Decimal
import json

async def request_validation_exception_handler(
    request: Request, exc: RequestValidationError
) -> JSONResponse:
    # Convert Decimal to str for JSON serialization
    for error in exc.errors():
        if 'ctx' in error and 'limit_value' in error['ctx']:
            error['ctx']['limit_value'] = str(error['ctx']['limit_value'])

    return JSONResponse(
        status_code=HTTP_422_UNPROCESSABLE_ENTITY, content={"detail": exc.errors()}
    )
```

```python
async def request_validation_exception_handler(
    request: Request, exc: RequestValidationError
) -> JSONResponse:
    # Serialize Decimal values to strings to avoid JSON serialization error
    errors = []
    for error in exc.errors():
        if 'ctx' in error and 'limit_value' in error['ctx']:
            error['ctx']['limit_value'] = str(error['ctx']['limit_value'])
        errors.append(error)

    return JSONResponse(
        status_code=HTTP_422_UNPROCESSABLE_ENTITY, content={"detail": errors}
    )
```

