async def request_validation_exception_handler(
    request: Request, exc: RequestValidationError
) -> JSONResponse:
    errors = exc.errors()
    # Convert Decimal values in the errors to float for JSON serialization
    for error in errors:
        if 'ctx' in error and 'limit_value' in error['ctx'] and isinstance(error['ctx']['limit_value'], Decimal):
            error['ctx']['limit_value'] = float(error['ctx']['limit_value'])
    return JSONResponse(
        status_code=HTTP_422_UNPROCESSABLE_ENTITY, content={"detail": errors}
    )
```

