```python
async def request_validation_exception_handler(
    request: Request, exc: RequestValidationError
) -> JSONResponse:
    # Serialize the errors to handle Decimal types properly
    errors = [{**error, "ctx": {k: (float(v) if isinstance(v, Decimal) else v) for k, v in error["ctx"].items()}} for error in exc.errors()]
    return JSONResponse(
        status_code=HTTP_422_UNPROCESSABLE_ENTITY, content={"detail": errors}
    )
```

