from fastapi.encoders import jsonable_encoder

async def request_validation_exception_handler(
    request: Request, exc: RequestValidationError
) -> JSONResponse:
    return JSONResponse(
        status_code=HTTP_422_UNPROCESSABLE_ENTITY, content={"detail": jsonable_encoder(exc.errors())}
    )
```

```python
async def request_validation_exception_handler(
    request: Request, exc: RequestValidationError
) -> JSONResponse:
    # Convert Decimal values in error messages to float for JSON serialization
    errors = [
        {**error, 'ctx': {**error['ctx'], 'limit_value': float(error['ctx'].get('limit_value', 0))}} 
        if 'ctx' in error and 'limit_value' in error['ctx'] and isinstance(error['ctx']['limit_value'], Decimal) 
        else error
        for error in exc.errors()
    ]
    return JSONResponse(
        status_code=HTTP_422_UNPROCESSABLE_ENTITY, content={"detail": errors}
    )
```
